SELECT t.*, p.name AS project_name FROM prj_task t JOIN prj_project p ON p.id = t.project_id WHERE 1 = 1
AND t.project_id = #{projectId}
AND t.status = #{status}
AND t.title LIKE CONCAT('%', #{kw}, '%')
ORDER BY t.id

mapper.update:
UPDATE prj_task SET title=#{title}, description=#{description}, assignee_id=#{assigneeId},
assignee_name=#{assigneeName}, priority=#{priority}, status=#{status}, progress=#{progress}, due_date=#{dueDate}
WHERE id=#{id}
